// C ABI of bada enigma, a bada-compatible v1.1 IME engine (docs/bada-compatible-v1.md; generated by
// export! in src/lib.rs). JSON in, JSON out. Returned strings belong to the engine and stay valid
// until the next call on the same engine.
#ifndef ENIGMA_H
#define ENIGMA_H

#include <stddef.h>
#include <stdint.h>

typedef struct EnigmaData EnigmaData;      // no data: pass NULL
typedef struct EnigmaEngine EnigmaEngine;

// Required.
EnigmaEngine *enigma_new(const EnigmaData *data);
void enigma_free(EnigmaEngine *engine);
const char *enigma_key(EnigmaEngine *engine, const char *event_json);
const char *enigma_set_mode(EnigmaEngine *engine, uint32_t mode);   // 0 muhenkan, else henkan
const char *enigma_flush(EnigmaEngine *engine);

// Optional, exported by bada enigma.
const char *enigma_set_settings(EnigmaEngine *engine, const char *settings_json);  // → settings in effect
const char *enigma_host_selection(EnigmaEngine *engine, const char *text);
const char *enigma_catalog(EnigmaEngine *engine);
const char *enigma_state(EnigmaEngine *engine);  // read-only: what's staged, mode, menu (§12)

// Not part of bada-compatible: the machine (rotor windows, the lit lamp, the setup) as JSON, for a
// lampboard. Valid until the next call to it.
const char *enigma_machine(EnigmaEngine *engine);

#endif
